import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test from 'node:test';

import { renderSpecLine } from './speckit-prepare-core.mjs';
import { resolveImplementRequester } from './speckit-prepare.mjs';
import { presentAmendment, resolveAmendment, startRework } from './speckit-amend.mjs';
import { ATTENTION_LABEL, BLOCKED_LABEL, DIAGNOSIS_COMMENT_MARKER, RETRY_COMMENT_MARKER, maintainDependencyBlock, parseFixEvents, renderFixEvent, setAttention, setBlocked } from './speckit-implement-core.mjs';
import { authoredFor, checkFixSpec, fixBlock, fixStamp, linkPrerequisite, maintainFixSpec, runEvidence, runRecord, settleClosedFix, startFixAuthoring } from './speckit-fix.mjs';
import { diagnosisRepo, silent } from './speckit-test-helpers.mjs';

const FOLDER = '20261014-100000-upload-expiry';
const PREFIX = `specs/${FOLDER}`;
const BRANCH = `speckit-spec/${FOLDER}`;

// The workflow_dispatch inputs an agentic workflow declares in its frontmatter.
function declaredInputs(file) {
  const source = readFileSync(new URL(`../workflows/${file}`, import.meta.url), 'utf8').replaceAll('\r\n', '\n');
  const block = source.match(/\n {4}inputs:\n([\s\S]*?)\n {2}\S/)?.[1] ?? '';
  return [...block.matchAll(/^ {6}([a-z_]+):$/gm)].map((match) => match[1]);
}
const env = (extra = {}) => ({ GITHUB_REPOSITORY: 'octo/repo', SPECKIT_DEFAULT_BRANCH: 'main', SPECKIT_TWIN: '5', SPECKIT_PULL: '9', SPECKIT_FOLDER: 'f', ...extra });
const SPEC = '# Feature Specification: Upload session expiry test\n\n## Summary\n\nMake the test independent of runner load.\n\n## Assumptions\n\n- `specs/f` depends on this spec.\n';
const PLAN = '# Plan\n\n## Architecture Updates\n\nNone: the fix changes a test only.\n';
const TASKS = '## Phase 1\n\n- [ ] T001 Use a longer SessionLifetime in UploadSessionExpiryTests\n';
const twinBody = (folder) => renderSpecLine({ serverUrl: 'https://github.com', repository: 'octo/repo', branch: 'main' }, folder);

// The implementation pull request #9 of twin #5 (`specs/f`), stopped and diagnosed, and the prerequisite spec pull
// request #12 an authoring run created (`branch` speckit-fix/<folder> for one opened by earlier tooling).
function fixRepo({ files = null, spec = SPEC, branch = BRANCH } = {}) {
  const github = diagnosisRepo({ amendment: false });
  github.issues[0].labels.push({ name: 'speckit:spec' });
  github.issues[0].body = twinBody('f');
  github.repo.branches[branch] = 'sha-fix';
  github.repo.commits['sha-fix'] = { tree: 't3', parents: ['sha-main'] };
  github.setFile('sha-fix', `${PREFIX}/spec.md`, spec);
  github.setFile('sha-fix', `${PREFIX}/plan.md`, PLAN);
  github.setFile('sha-fix', `${PREFIX}/tasks.md`, TASKS);
  github.setFile('sha-fix', `${PREFIX}/checklists/requirements.md`, '- [x] Requirements are testable\n');
  github.repo.pulls.push({ number: 12, node_id: 'PR_12', title: 'Fix spec: Upload session expiry', html_url: 'https://github.com/octo/repo/pull/12', body: 'Agent body <!-- speckit-fix:for {"pull":99} -->\n\n> Generated by [Spec Kit fix](https://github.com/octo/repo/actions/runs/1)\n\n<!-- gh-aw-agentic-workflow: Spec Kit fix, engine: copilot, id: 1 -->\n\n<!-- gh-aw-workflow-id: speckit-fix -->\n<!-- unterminated', draft: true, state: 'open', assignees: [], base: { ref: 'main', sha: 'sha-main' }, head: { ref: branch, sha: 'sha-fix', repo: { full_name: 'octo/repo' } }, created_at: github.tick() });
  github.repo.pullFiles[12] = files ?? [`${PREFIX}/spec.md`, `${PREFIX}/plan.md`, `${PREFIX}/tasks.md`, `${PREFIX}/checklists/requirements.md`];
  return github;
}

async function authored(github, extra = {}, actor = 'dev') {
  await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation: await github.getPullRequest(9), guidance: 'Make the test robust', actor, now: github.clock });
  const check = github.repo.checkRuns.at(-1);
  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-'));
  try {
    const output = path.join(dir, 'agent_output.json');
    writeFileSync(output, JSON.stringify({ items: [{ type: 'speckit_fix', report: JSON.stringify({ folder: FOLDER, summary: 'Lengthens the session lifetime of the expiry test.' }) }] }));
    return await runRecord({ client: github, env: env({ GH_AW_AGENT_OUTPUT: output, SPECKIT_CHECK_RUN: String(check.id), SPECKIT_DETECTION: 'success', SPECKIT_CREATED_PULL: '12', ...extra }), log: silent });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const addTwin = (github, number, folder, labels = []) => github.issues.push({ number, id: number * 1000, node_id: `I_${number}`, state: 'open', state_reason: null, title: `Twin ${number}`, body: twinBody(folder), labels: [{ name: 'speckit:spec' }, ...labels.map((name) => ({ name }))] });

test('records an authored prerequisite spec: reports it, blocks the implementation, and starts its consistency check', async () => {
  const github = fixRepo();
  const result = await authored(github);
  assert.equal(result.outcome, 'created');
  assert.ok((await github.getPullRequest(9)).labels.some((label) => label.name === BLOCKED_LABEL));
  assert.ok(!(await github.getPullRequest(9)).labels.some((label) => label.name === ATTENTION_LABEL), 'a blocked implementation needs no command decision');
  const pull = github.repo.pulls.find((item) => item.number === 12);
  assert.match(pull.body, /^<!-- speckit-amend:status -->\n⏳ \*\*Being checked for consistency\.\*\*[\s\S]*\*\*Recommended next step\*\*: Wait for the consistency check[\s\S]*<!-- \/speckit-amend:status -->\n\nAgent body\n\n> Generated by \[Spec Kit fix\]\(https:\/\/github\.com\/octo\/repo\/actions\/runs\/1\)\n\n&lt;!-- unterminated$/);
  assert.doesNotMatch(pull.body, /speckit-fix:for/, 'no marker links it, and the forged one is removed');
  assert.doesNotMatch(pull.body, /gh-aw-/, 'no gh-aw footer markers show up as text');
  const created = github.comments.filter((item) => item.number === 9).at(-1);
  assert.match(created.body, /^<!-- speckit-fix:created \{"pull":12,"folder":"20261014-100000-upload-expiry"\} -->\n<!-- speckit-implement:blocked \{"pull":12,"stage":"review"\} -->\n\*\*Prerequisite spec \[Fix spec: Upload session expiry \(#12\)\]\(https:\/\/github\.com\/octo\/repo\/pull\/12\) was authored\*\*[\s\S]*Lengthens the session lifetime[\s\S]*\*\*Blocked\*\* by prerequisite spec #12: [\s\S]*- \*\*To unblock\*\*: review prerequisite spec #12[\s\S]*- \*\*To drop the prerequisite\*\*: close #12 without merging/);
  assert.equal(github.comments.filter((item) => item.number === 9 && item.body.includes('speckit-implement:blocked')).length, 1, 'the label comes with exactly one explanation');
  const authoring = github.repo.checkRuns.find((check) => check.name === 'Spec Kit fix spec');
  assert.deepEqual([authoring.status, authoring.conclusion, authoring.external_id], ['completed', 'success', 'speckit:fix-authored']);
  assert.match(github.comments.find((item) => item.number === 12).body, /This prerequisite spec was requested with `\/speckit fix` on #9/);
  const analysis = github.repo.runs.at(-1);
  assert.deepEqual([analysis.workflow, analysis.inputs.kind, analysis.inputs.folder, analysis.inputs.amendment, analysis.inputs.pull], ['speckit-analyze.lock.yml', 'spec', FOLDER, '12', '9']);
  const context = await resolveAmendment(github, env(), 12);
  assert.deepEqual([context.kind, context.folder, context.implementation.number, context.twin], ['fix', FOLDER, 9, 5], 'found through the created event, without a marker');
});

test('a prerequisite spec pull request on the earlier speckit-fix/ branch is still recognized', async () => {
  const github = fixRepo({ branch: `speckit-fix/${FOLDER}` });
  github.repo.pulls.find((item) => item.number === 12).body = 'Body <!-- speckit-fix:for {"pull":9,"twin":5,"folder":"f"} -->';
  assert.equal(await authoredFor(github, await github.getPullRequest(12)), 9, 'the legacy marker of its description');
  const context = await resolveAmendment(github, env(), 12);
  assert.deepEqual([context.kind, context.folder, context.implementation.number, context.twin], ['fix', FOLDER, 9, 5]);
  await startRework(github, env(), context, { mode: 'revise', feedback: { items: [] } });
  const rework = github.repo.runs.at(-1);
  assert.deepEqual([rework.workflow, rework.inputs.mode, rework.inputs.branch], ['speckit-fix.lock.yml', 'revise', undefined], 'the earlier workflow finds the legacy branch by its folder');
  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-legacy-'));
  try {
    const { context: revise } = await runEvidence({ client: github, env: env({ SPECKIT_EVIDENCE_DIR: dir, SPECKIT_MODE: 'revise', SPECKIT_AMENDMENT: '12', SPECKIT_FOLDER: FOLDER }), log: silent });
    assert.equal(revise.branch, `speckit-fix/${FOLDER}`);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
  github.closePull(12);
  assert.equal((await settleClosedFix(github, env(), { amendment: await github.getPullRequest(12), folder: FOLDER, implementation: await github.getPullRequest(9) })).outcome, 'discarded');
  assert.equal(github.repo.branches[`speckit-fix/${FOLDER}`], undefined, 'its own branch is deleted');
});

test('a prerequisite spec is owned by the person who asked for it with /speckit fix, from its creation to its review', async () => {
  const github = fixRepo();
  await authored(github, {}, 'fixer');
  const pull = github.repo.pulls.find((item) => item.number === 12);
  assert.deepEqual(pull.assignees, ['fixer'], 'assigned when it is created, not the implementation requester');
  assert.match(github.comments.find((item) => item.number === 12).body, /then it is handed to @fixer for review/);
  await presentAmendment(github, env(), await resolveAmendment(github, env(), 12), { consistent: true });
  assert.deepEqual(pull.assignees, ['fixer'], 'not assigned twice');
  assert.deepEqual(github.repo.reviewRequests, [{ number: 12, reviewers: ['fixer'] }]);
  for (const body of [
    pull.body,
    github.comments.filter((item) => item.number === 12).at(-1).body,
    github.comments.filter((item) => item.number === 9).at(-1).body,
  ]) {
    assert.equal(body.match(/\*\*Recommended next step\*\*/g)?.length, 1);
    assert.match(body, /\*\*Recommended next step\*\*: Review and merge prerequisite spec \[#12\]\(https:\/\/github\.com\/octo\/repo\/pull\/12\)\./);
    assert.match(body, /Adds the prerequisite spec to `main`, makes this spec depend on it, and requests its implementation automatically/);
    assert.match(body, /#9 waits and retries by itself once it is implemented/);
  }
  await presentAmendment(github, env(), await resolveAmendment(github, env(), 12), { consistent: false, problem: 'correction round did not finish' });
  for (const body of [
    pull.body,
    github.comments.filter((item) => item.number === 12).at(-1).body,
    github.comments.filter((item) => item.number === 9).at(-1).body,
  ]) {
    assert.equal(body.match(/\*\*Recommended next step\*\*/g)?.length, 1);
    assert.match(body, /\*\*Recommended next step\*\*: Post the following comment on prerequisite spec \[#12\]/);
    assert.match(body, /```text\nPlease rework this prerequisite spec [^\n]+\n```/);
    assert.doesNotMatch(body, /\*\*Recommended next step\*\*: Review and merge/);
  }
});

test('a missing, refused, or broken prerequisite spec goes back to the implementation with the next steps', async () => {
  const none = fixRepo();
  const result = await authored(none, { SPECKIT_CREATED_PULL: '' });
  assert.equal(result.outcome, 'none');
  assert.match(none.comments.at(-1).body, /^\*\*No prerequisite spec was created\*\*: Lengthens the session lifetime[\s\S]*\*\*Recommended next step\*\*: Retry what stopped[\s\S]*```text\n\/speckit retry\n```/);

  const broken = fixRepo({ files: [`${PREFIX}/spec.md`, 'src/platform/Tests/UploadSessionExpiryTests.cs'] });
  assert.equal((await authored(broken)).outcome, 'rejected');
  assert.equal(broken.repo.pulls.find((item) => item.number === 12).state, 'closed');
  assert.equal(broken.repo.branches[BRANCH], undefined);
  assert.match(broken.comments.at(-1).body, /^\*\*The authored prerequisite spec #12 was rejected and closed\*\*: it changes files outside `specs\/20261014-100000-upload-expiry\/`: `src\/platform\/Tests\/UploadSessionExpiryTests\.cs`/);
  assert.equal(broken.repo.checkRuns.find((check) => check.name === 'Spec Kit fix spec').conclusion, 'failure');

  const elsewhere = fixRepo({ branch: `feature/${FOLDER}` });
  assert.equal((await authored(elsewhere)).outcome, 'rejected');
  assert.match(elsewhere.comments.at(-1).body, /its branch `feature\/20261014-100000-upload-expiry` is not `speckit-spec\/<folder>`/);
});

test('checks a prerequisite spec: a new, publishable spec folder, without a Fix for line', async () => {
  const github = fixRepo();
  assert.doesNotMatch(SPEC, /Fix for/);
  assert.deepEqual((await checkFixSpec(github, { folder: FOLDER, pull: await github.getPullRequest(12) })).reasons, []);

  const listed = fixRepo({ files: [`${PREFIX}/spec.md`, `${PREFIX}/plan.md`, `${PREFIX}/tasks.md`, 'specs/README.md'] });
  const reasons = (await checkFixSpec(listed, { folder: FOLDER, pull: await listed.getPullRequest(12) })).reasons.join('\n');
  assert.match(reasons, /may only add `specs\/20261014-100000-upload-expiry\/` \(specs\/README\.md lists no specs\), but it changes `specs\/README\.md`/);
  assert.doesNotMatch(reasons, /Fix for/);

  const existing = fixRepo({ files: [`${PREFIX}/spec.md`, 'docs/architecture/overview.md'] });
  existing.setFile('main', `${PREFIX}/spec.md`, SPEC);
  const more = (await checkFixSpec(existing, { folder: FOLDER, pull: await existing.getPullRequest(12) })).reasons.join('\n');
  assert.match(more, /may only add `specs\/20261014-100000-upload-expiry\/` \(specs\/README\.md lists no specs\), but it changes `docs\/architecture\/overview\.md`/);
  assert.match(more, /already exists on `main`/);
});

test('a prerequisite spec is reworked by Spec Kit fix, and its evidence names the branch prefix and the spec that depends on it', async () => {
  const github = fixRepo();
  await authored(github);
  const context = await resolveAmendment(github, env(), 12);
  await startRework(github, env(), context, { mode: 'revise', feedback: { items: [{ kind: 'comment', author: 'dev', body: 'Keep the 2 s sweep check.', at: github.tick() }] } });
  const rework = github.repo.runs.at(-1);
  assert.deepEqual([rework.workflow, rework.inputs.mode, rework.inputs.amendment, rework.inputs.folder, rework.inputs.branch], ['speckit-fix.lock.yml', 'revise', '12', FOLDER, BRANCH]);
  // GitHub rejects a dispatch with an input the workflow does not declare.
  for (const run of github.repo.runs.filter((item) => item.workflow.endsWith('.lock.yml'))) {
    const declared = declaredInputs(run.workflow.replace('.lock.yml', '.md'));
    assert.deepEqual(Object.keys(run.inputs).filter((name) => !declared.includes(name)), [], `${run.workflow} declares every input it is dispatched with`);
  }
  assert.match(github.comments.filter((item) => item.number === 12).at(-1).body, /\*\*Reworking this prerequisite spec\*\* with the feedback from @dev/);

  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-evidence-'));
  try {
    await github.createComment(9, `${DIAGNOSIS_COMMENT_MARKER}\n**Diagnosis**: a flaky test from another feature.`);
    const { context: author } = await runEvidence({ client: github, env: env({ SPECKIT_EVIDENCE_DIR: dir, SPECKIT_STAMP: '20261014-100000' }), log: silent, now: () => github.clock });
    assert.deepEqual([author.folderPrefix, author.branchPrefix, author.titlePrefix, author.prerequisiteOf], ['20261014-100000-', 'speckit-spec/', 'Fix spec: ', 'specs/f']);
    assert.equal('fixForLine' in author, false, 'new specs carry no Fix for line');
    const evidence = readFileSync(path.join(dir, 'evidence.md'), 'utf8');
    assert.match(evidence, /## Guidance from the person who asked for the prerequisite spec\n\nMake the test robust/);
    assert.match(evidence, /## Latest diagnosis\n\n<!-- speckit-implement:diagnosis -->\n\*\*Diagnosis\*\*: a flaky test/);
    const { context: revise } = await runEvidence({ client: github, env: env({ SPECKIT_EVIDENCE_DIR: dir, SPECKIT_MODE: 'revise', SPECKIT_AMENDMENT: '12', SPECKIT_FOLDER: FOLDER, SPECKIT_GUIDANCE: 'Keep the sweep check.' }), log: silent });
    assert.deepEqual([revise.specDir, revise.branch, revise.fixPull, revise.baseBranch, revise.prerequisiteOf], [PREFIX, BRANCH, 12, 'main', 'specs/f']);
    assert.equal('fixForLine' in revise, false);
    assert.match(readFileSync(path.join(dir, 'evidence.md'), 'utf8'), /## Feedback on the prerequisite spec to address\n\nKeep the sweep check\./);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('after the merge, the stopped spec depends on the prerequisite twin, which is requested; the implementation retries once it is implemented', async () => {
  const github = fixRepo();
  github.permissions.dev = 'write';
  await authored(github);
  github.closePull(12, { merged: true });
  const implementation = github.repo.pulls.find((pull) => pull.number === 9);
  const maintain = () => maintainFixSpec(github, env(), { folder: 'f', implementation, twin: 5 }, { now: github.clock, report: silent });
  const dependency = () => maintainDependencyBlock(github, env(), { implementation, twin: 5 }, { report: silent });
  const blocked = () => (implementation.labels ?? []).some((label) => label.name === BLOCKED_LABEL);

  assert.deepEqual(await maintain(), { outcome: 'waiting', blocked: true }, 'the twin does not exist before Spec Kit prepare ran');
  assert.equal(blocked(), true);
  assert.equal((implementation.labels ?? []).some((label) => label.name === ATTENTION_LABEL), false, 'waiting for a prerequisite needs no command decision');
  assert.match(github.comments.filter((item) => item.number === 9).at(-1).body, /^<!-- speckit-fix:merged \{"pull":12,[\s\S]*<!-- speckit-implement:blocked \{"pull":12,"stage":"implement"\} -->\n\*\*Prerequisite spec #12 was merged\*\* into `main` by a person[\s\S]*\*\*Blocked\*\* by prerequisite spec #12: it is merged[\s\S]*- \*\*Unblocks by itself\*\* once its spec twin is implemented/);
  assert.equal(github.repo.branches[BRANCH], undefined);

  addTwin(github, 30, FOLDER, ['speckit:stage:tasked', 'speckit:deps-pending']);
  assert.deepEqual(await maintain(), { outcome: 'waiting', blocked: true }, 'its dependency inference runs first');
  assert.deepEqual(github.edges, []);
  github.find(30).labels = github.find(30).labels.filter((label) => label.name !== 'speckit:deps-pending');
  assert.deepEqual(await maintain(), { outcome: 'linked', blocked: false });
  assert.deepEqual(github.edges, [[5, 30]], 'the stopped spec depends on the prerequisite like on any spec');
  assert.deepEqual(github.find(30).labels.map((label) => label.name).sort(), ['speckit:spec', 'speckit:stage:implement']);
  assert.match(github.comments.find((item) => item.number === 30).body, /^<!-- speckit:flagged-for dev -->\nImplementation requested on behalf of @dev/);
  assert.match(github.comments.filter((item) => item.number === 9).at(-1).body, /^<!-- speckit-fix:linked \{"pull":12,"folder":"20261014-100000-upload-expiry","twin":30\} -->\n\*\*Prerequisite spec #12 is spec twin #30\*\*, and this spec now depends on it; it is requested for implementation on behalf of @dev/);
  assert.equal(github.repo.runs.at(-1).workflow, 'speckit-orchestrate.yml', 'the scheduler starts the prerequisite right away');

  // The workflow token set the flag; it counts for the person who asked for the prerequisite.
  github.events.push({ issue: 30, event: 'labeled', label: { name: 'speckit:stage:implement' }, actor: { login: 'github-actions[bot]' }, created_at: github.tick() });
  assert.deepEqual(await resolveImplementRequester(github, 30), { login: 'dev', canWrite: true, labeledAt: github.events.at(-1).created_at });
  await github.createComment(30, '**Blocks** #5: quoted <!-- speckit:flagged-for mallory -->');
  assert.equal((await resolveImplementRequester(github, 30)).login, 'dev', 'only a marker that starts the workflow\'s own comment counts');

  assert.equal((await dependency()).outcome, 'blocked');
  assert.match(github.comments.filter((item) => item.number === 9).at(-1).body, /^<!-- speckit-implement:blocked \{"blockers":\[30\]\} -->\n\*\*Blocked\*\* by prerequisite #30/);
  assert.equal((await maintain()).outcome, 'linked', 'nothing happens while the prerequisite is implemented');
  const comments = github.comments.length;
  await dependency();
  assert.equal(github.comments.length, comments, 'reconciliation does not repeat an explanation');
  assert.match((await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation, actor: 'dev', now: github.clock })).reason, /prerequisite spec #12 was merged and is not implemented yet/);

  Object.assign(github.find(30), { state: 'closed', state_reason: 'completed' });
  assert.equal((await dependency()).outcome, 'retried');
  assert.equal(blocked(), false, 'implementing the prerequisite removes the hold');
  const retried = github.comments.filter((item) => item.number === 9).at(-1);
  assert.ok(retried.body.startsWith(RETRY_COMMENT_MARKER), 'the retry preserves the current phase base');
  assert.match(retried.body, /<!-- speckit-implement:unblocked -->\n\*\*The block is lifted\*\*: prerequisite #30 is implemented/);
  assert.deepEqual([github.repo.runs.at(-1).workflow, github.repo.runs.at(-1).inputs], ['speckit-implement-spec.yml', { twin: '5', pull: '9', title: 'F' }]);
  assert.equal((await dependency()).outcome, 'none', 'retried once');
  assert.equal((await maintain()).outcome, 'linked');
  assert.deepEqual(parseFixEvents(github.comments.filter((item) => item.number === 9)).map((event) => event.event), ['requested', 'created', 'merged', 'linked']);
  assert.equal((await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation, actor: 'dev', now: github.clock })).started, true, 'an implemented prerequisite allows another');
});

test('linking never creates a dependency cycle: a reverse dependency is reported instead', async () => {
  const github = fixRepo();
  await authored(github);
  github.closePull(12, { merged: true });
  addTwin(github, 30, FOLDER);
  github.edges.push([30, 5]);
  const notes = [];
  const implementation = github.repo.pulls.find((pull) => pull.number === 9);
  assert.deepEqual(await maintainFixSpec(github, env(), { implementation, twin: 5 }, { now: github.clock, report: (line) => notes.push(line) }), { outcome: 'cycle', blocked: true });
  assert.deepEqual(github.edges, [[30, 5]], 'no cycle');
  assert.match(notes.join('\n'), /spec twin #30 already depends on #5, so #5 cannot depend on it without a dependency cycle/);
  assert.deepEqual(await linkPrerequisite(github, { twin: 5, prerequisite: github.find(30) }), { linked: false, outcome: 'cycle' });
  github.edges.length = 0;
  github.edges.push([5, 30]);
  assert.deepEqual(await linkPrerequisite(github, { twin: 5, prerequisite: github.find(30) }), { linked: true }, 'an existing dependency counts');
  assert.deepEqual(github.edges, [[5, 30]]);
});

test('one cause, one prerequisite spec: /speckit fix on another implementation joins the existing one', async () => {
  const github = fixRepo();
  github.permissions.dev = 'write';
  await authored(github);
  github.issues.push({ number: 6, id: 6000, node_id: 'I_6', state: 'open', title: 'G', body: twinBody('g'), labels: [{ name: 'speckit:spec' }] });
  github.repo.pulls.push({ number: 20, node_id: 'PR_20', title: 'Implement: G', body: 'Closes #6', draft: true, state: 'open', labels: [], base: { ref: 'main' }, head: { ref: 'speckit/g', sha: 'sha-impl-g', repo: { full_name: 'octo/repo' } }, created_at: github.tick() });
  const second = env({ SPECKIT_TWIN: '6', SPECKIT_PULL: '20', SPECKIT_FOLDER: 'g' });

  const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-join-'));
  try {
    const { context } = await runEvidence({ client: github, env: { ...second, SPECKIT_EVIDENCE_DIR: dir, SPECKIT_STAMP: '20261014-110000' }, log: silent, now: () => github.clock });
    assert.deepEqual(context.existingFixes, [{ pull: 12, folder: FOLDER, state: 'open', title: 'Fix spec: Upload session expiry' }]);
    const evidence = readFileSync(path.join(dir, 'evidence.md'), 'utf8');
    assert.match(evidence, /## Existing prerequisite specs\n\nOne cause gets one spec\.[\s\S]*report its pull request number in `reuse`/);
    assert.match(evidence, /### #12 Fix spec: Upload session expiry \(`specs\/20261014-100000-upload-expiry`, open for review, asked for by #9\)\n\n# Feature Specification: Upload session expiry test/);

    await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 6, implementation: await github.getPullRequest(20), actor: 'dev', now: github.clock });
    const output = path.join(dir, 'agent_output.json');
    writeFileSync(output, JSON.stringify({ items: [{ type: 'speckit_fix', report: JSON.stringify({ reuse: '#12', summary: 'The same flaky expiry test stops this implementation.' }) }] }));
    const runs = github.repo.runs.length;
    const joined = await runRecord({ client: github, env: { ...second, GH_AW_AGENT_OUTPUT: output, SPECKIT_CHECK_RUN: String(github.repo.checkRuns.at(-1).id), SPECKIT_DETECTION: 'success', SPECKIT_CREATED_PULL: '' }, log: silent });
    assert.deepEqual([joined.outcome, joined.pull], ['joined', 12]);
    assert.equal(github.repo.runs.length, runs, 'no second consistency check');
    assert.equal(github.repo.pulls.filter((pull) => String(pull.head.ref).startsWith('speckit-spec/')).length, 1, 'no second prerequisite spec');
    assert.match(github.comments.filter((item) => item.number === 20).at(-1).body, /^<!-- speckit-fix:created \{"pull":12,"folder":"20261014-100000-upload-expiry","joined":true\} -->\n<!-- speckit-implement:blocked \{"pull":12,"stage":"review"\} -->\n\*\*This stop has the same cause as prerequisite spec \[#12\]\(https:\/\/github\.com\/octo\/repo\/pull\/12\)\*\*[\s\S]*The same flaky expiry test/);
    assert.match(github.comments.filter((item) => item.number === 12).at(-1).body, /^\*\*Also unblocks #20\*\* \(`specs\/g`\)/);
    const authoring = github.repo.checkRuns.at(-1);
    assert.deepEqual([authoring.conclusion, authoring.output.title], ['success', 'Joined prerequisite spec #12']);
    const implementation = github.repo.pulls.find((pull) => pull.number === 20);
    assert.ok(implementation.labels.some((label) => label.name === BLOCKED_LABEL));
    assert.equal((await resolveAmendment(github, env(), 12)).implementation.number, 9, 'it belongs to the implementation it was authored for');

    const maintain = (number, twin) => maintainFixSpec(github, env(), { implementation: github.repo.pulls.find((pull) => pull.number === number), twin }, { now: github.clock, report: silent });
    const before = github.repo.runs.length;
    assert.equal((await maintain(20, 6)).outcome, 'joined', 'the prerequisite spec is maintained by the implementation it was authored for');
    assert.equal(github.repo.runs.length, before);
    assert.match((await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 6, implementation, actor: 'dev', now: github.clock })).reason, /prerequisite spec #12 is still open/);

    github.closePull(12, { merged: true });
    addTwin(github, 30, FOLDER);
    const { context: merged } = await runEvidence({ client: github, env: { ...second, SPECKIT_EVIDENCE_DIR: dir, SPECKIT_STAMP: '20261014-120000' }, log: silent, now: () => github.clock });
    assert.deepEqual(merged.existingFixes, [{ pull: 12, folder: FOLDER, state: 'merged', title: 'Fix spec: Upload session expiry' }], 'a merged prerequisite an implementation waits for, found without a Fix for line');
    assert.equal((await maintain(9, 5)).outcome, 'linked');
    assert.equal((await maintain(20, 6)).outcome, 'linked');
    assert.deepEqual(github.edges, [[5, 30], [6, 30]], 'both stopped specs depend on the one prerequisite');
    Object.assign(github.find(30), { state: 'closed', state_reason: 'completed' });
    for (const [number, twin] of [[20, 6], [9, 5]]) {
      const result = await maintainDependencyBlock(github, env(), { implementation: github.repo.pulls.find((pull) => pull.number === number), twin }, { report: silent });
      assert.equal(result.outcome, 'retried');
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('a reuse must name an existing prerequisite spec; a spec created anyway for the same cause is discarded', async () => {
  const report = async (github, fields, created = '') => {
    await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation: await github.getPullRequest(9), actor: 'dev', now: github.clock });
    const dir = mkdtempSync(path.join(tmpdir(), 'speckit-fix-reuse-'));
    try {
      const output = path.join(dir, 'agent_output.json');
      writeFileSync(output, JSON.stringify({ items: [{ type: 'speckit_fix', report: JSON.stringify(fields) }] }));
      return await runRecord({ client: github, env: env({ GH_AW_AGENT_OUTPUT: output, SPECKIT_CHECK_RUN: String(github.repo.checkRuns.at(-1).id), SPECKIT_DETECTION: 'success', SPECKIT_CREATED_PULL: created }), log: silent });
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  };
  const invalid = fixRepo();
  const refused = await report(invalid, { reuse: 77 });
  assert.equal(refused.outcome, 'none');
  assert.match(invalid.comments.filter((item) => item.number === 9).at(-1).body, /\*\*No prerequisite spec was created\*\*: the agent named prerequisite spec #77 for this cause, but it is neither an open prerequisite spec pull request nor a merged prerequisite spec/);

  const duplicate = fixRepo();
  duplicate.repo.branches['speckit-spec/20261014-120000-other'] = 'sha-fix';
  duplicate.repo.pulls.push({ number: 13, node_id: 'PR_13', title: 'Fix spec: Duplicate', body: '', draft: true, state: 'open', assignees: [], base: { ref: 'main' }, head: { ref: 'speckit-spec/20261014-120000-other', sha: 'sha-fix', repo: { full_name: 'octo/repo' } }, created_at: duplicate.tick() });
  const joined = await report(duplicate, { reuse: 12, summary: 'Same cause.' }, '13');
  assert.deepEqual([joined.outcome, joined.pull], ['joined', 12]);
  assert.equal(duplicate.repo.pulls.find((pull) => pull.number === 13).state, 'closed', 'the duplicate is closed');
  assert.equal(duplicate.repo.branches['speckit-spec/20261014-120000-other'], undefined);
});

test('a discarded prerequisite spec, or one that is not implemented, stops for a person; a pending one refuses another', async () => {
  const github = fixRepo();
  await authored(github);
  const implementation = github.repo.pulls.find((pull) => pull.number === 9);
  await maintainFixSpec(github, env(), { implementation, twin: 5 }, { now: github.clock, report: silent });
  assert.ok(implementation.labels.some((label) => label.name === BLOCKED_LABEL), 'reviewing the prerequisite holds the implementation');
  assert.equal((await maintainDependencyBlock(github, env(), { implementation, twin: 5, hold: true }, { report: silent })).outcome, 'held', 'the review holds it although the twin has no dependency yet');
  assert.ok(implementation.labels.some((label) => label.name === BLOCKED_LABEL));
  const again = await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation, actor: 'dev', now: github.clock });
  assert.match(again.reason, /prerequisite spec #12 is still open/);
  github.closePull(12);
  const settled = await settleClosedFix(github, env(), { amendment: await github.getPullRequest(12), folder: FOLDER, implementation, actor: 'dev' });
  assert.equal(settled.outcome, 'discarded');
  assert.ok(!implementation.labels.some((label) => label.name === BLOCKED_LABEL));
  assert.ok(implementation.labels.some((label) => label.name === ATTENTION_LABEL), 'discarding the prerequisite needs a new decision');
  assert.match(github.comments.at(-1).body, /^<!-- speckit-fix:discarded \{"pull":12,[\s\S]*\*\*Prerequisite spec #12 was closed without merging\*\* by @dev\. The block is lifted[\s\S]*\*\*Recommended next step\*\*/);
  assert.equal((await settleClosedFix(github, env(), { amendment: await github.getPullRequest(12), folder: FOLDER, implementation })).outcome, 'handled');
  assert.equal((await maintainDependencyBlock(github, env(), { implementation, twin: 5 }, { report: silent })).outcome, 'none', 'nothing to lift or retry');
  assert.equal((await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation, actor: 'dev', now: github.clock + 3 * 60 * 60 * 1000 })).started, true, 'a discarded prerequisite spec can be requested again');

  const stopped = fixRepo();
  await authored(stopped);
  stopped.closePull(12, { merged: true });
  addTwin(stopped, 30, FOLDER);
  const pull = stopped.repo.pulls.find((item) => item.number === 9);
  await maintainFixSpec(stopped, env(), { implementation: pull, twin: 5 }, { now: stopped.clock, report: silent });
  await maintainDependencyBlock(stopped, env(), { implementation: pull, twin: 5 }, { report: silent });
  Object.assign(stopped.find(30), { state: 'closed', state_reason: 'not_planned' });
  assert.equal((await maintainDependencyBlock(stopped, env(), { implementation: pull, twin: 5 }, { report: silent })).outcome, 'stopped');
  const stoppedPull = await stopped.getPullRequest(9);
  assert.ok(!stoppedPull.labels.some((label) => label.name === BLOCKED_LABEL));
  assert.ok(stoppedPull.labels.some((label) => label.name === ATTENTION_LABEL));
  assert.match(stopped.comments.at(-1).body, /^<!-- speckit-implement:unblocked -->\n\*\*A prerequisite was not implemented\*\*: #30 was closed without being implemented/);
});

test('a fix spec linked by earlier tooling is an ordinary dependency: the missing one is added and the block explained once', async () => {
  const github = fixRepo({ branch: `speckit-fix/${FOLDER}` });
  github.closePull(12, { merged: true });
  // Recorded by earlier tooling: lifecycle markers only, and a diagnosis that asked for attention.
  await github.createComment(9, renderFixEvent('created', { pull: 12, folder: FOLDER }));
  await github.createComment(9, renderFixEvent('merged', { pull: 12, folder: FOLDER }));
  await github.createComment(9, renderFixEvent('linked', { pull: 12, folder: FOLDER, twin: 30 }));
  await github.addLabels(9, [ATTENTION_LABEL]);
  addTwin(github, 30, FOLDER);
  const implementation = github.repo.pulls.find((pull) => pull.number === 9);
  assert.deepEqual(await maintainFixSpec(github, env(), { implementation, twin: 5 }, { now: github.clock, report: silent }), { outcome: 'linked', blocked: false });
  assert.deepEqual(github.edges, [[5, 30]]);
  await maintainDependencyBlock(github, env(), { implementation, twin: 5 }, { report: silent });
  assert.deepEqual(implementation.labels.map((label) => label.name), [BLOCKED_LABEL]);
  assert.match(github.comments.at(-1).body, /^<!-- speckit-implement:blocked \{"blockers":\[30\]\} -->\n\*\*Blocked\*\* by prerequisite #30/);
  const count = github.comments.length;
  await maintainDependencyBlock(github, env(), { implementation, twin: 5 }, { report: silent });
  assert.equal(github.comments.length, count);
  Object.assign(github.find(30), { state: 'closed', state_reason: 'completed' });
  assert.equal((await maintainDependencyBlock(github, env(), { implementation, twin: 5 }, { report: silent })).outcome, 'retried');
});

test('a blocked label always comes with one explanation, replaces the attention label, and is not set on closed pull requests', async () => {
  const github = fixRepo();
  const implementation = github.repo.pulls.find((pull) => pull.number === 9);
  await github.addLabels(9, ['bug', ATTENTION_LABEL]);
  await assert.rejects(setBlocked(github, 9, true), /needs an explanation/);
  const explain = fixBlock({ stage: 'implement', fixPull: 12, fixTwin: 30, baseBranch: 'main' });
  await setBlocked(github, 9, true, { explain });
  assert.deepEqual(implementation.labels.map((label) => label.name).sort(), [BLOCKED_LABEL, 'bug'].sort());
  assert.ok(github.labels.has(BLOCKED_LABEL), 'creates the custom label when missing');
  const posted = github.comments.filter((item) => item.number === 9);
  assert.equal(posted.length, 1);
  assert.match(posted[0].body, /^<!-- speckit-implement:blocked \{"pull":12,"stage":"implement"\} -->\n\*\*Blocked\*\* by prerequisite spec #12 \(spec twin #30\)[\s\S]*- \*\*Unblocks by itself\*\* once #30 is implemented: this spec depends on it/);
  await setAttention(github, 9, true);
  assert.ok(!implementation.labels.some((label) => label.name === ATTENTION_LABEL), 'a blocked pull request does not ask for attention');
  await setBlocked(github, 9, true, { explain });
  assert.equal(github.comments.filter((item) => item.number === 9).length, 1, 'an explained block is not explained again');
  github.closePull(9);
  await setBlocked(github, 9, true, { explain });
  assert.deepEqual(implementation.labels.map((label) => label.name), ['bug']);
});

test('prerequisite specs are added to the default branch only, with a UTC folder stamp', async () => {
  const github = fixRepo();
  github.repo.pulls[0].base.ref = 'release';
  const refused = await startFixAuthoring(github, { SPECKIT_DEFAULT_BRANCH: 'main' }, { twin: 5, implementation: await github.getPullRequest(9), actor: 'dev' });
  assert.match(refused.reason, /base branch `release` is not the default branch `main`, where prerequisite specs are added/);
  assert.equal(fixStamp(Date.parse('2026-10-14T08:23:07Z')), '20261014-082307');
});
